from fastapi import Request, Response
from fastapi.responses import JSONResponse
from rate_limiter import TokenBucket
from config import TIER_LIMITS, WHITELIST_PATHS

buckets = {}

def get_bucket(client_id: str, tier: str = 'FREE'):
    if client_id not in buckets:
        cap, rate = TIER_LIMITS.get(tier, (10, 10 / 60.0))
        buckets[client_id] = TokenBucket(cap, rate)
    return buckets[client_id]

async def rate_limit_middleware(request: Request, call_next):
    if request.url.path in WHITELIST_PATHS:
        return await call_next(request)
    client_id = request.headers.get('X-API-Key') or (request.client.host if request.client else '127.0.0.1')
    tier = request.headers.get('X-Tier', 'FREE')
    bucket = get_bucket(client_id, tier)
    if not bucket.consume(1):
        retry_after = max(1, int((1.0 - bucket.tokens) / max(bucket.refill_rate, 0.001)))
        return JSONResponse(
            status_code=429,
            content={'error': 'Too Many Requests'},
            headers={'Retry-After': str(retry_after), 'X-RateLimit-Limit': str(bucket.capacity), 'X-RateLimit-Remaining': '0'}
        )
    response = await call_next(request)
    response.headers['X-RateLimit-Limit'] = str(bucket.capacity)
    response.headers['X-RateLimit-Remaining'] = str(int(bucket.tokens))
    return response

