from rest_framework import permissions

class IsInvoiceTenantOwner(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        user_org = getattr(request.user, 'organization', None) or getattr(request.user.profile, 'organization', None)
        return obj.organization_id == getattr(user_org, 'id', user_org)

